files.samples/tests/_tools/sample-capture-html:
# Read an HTML table off the page as rows of cell text, header row first, so a
# later step can compare it against a stored fixture. Whitespace inside a cell
# is collapsed to single spaces: rendered markup indents text that a person
# reads as one line.
runtime: js-page
description: >-
  Capture the HTML table matching the CSS selector as string[][] (header row
  first, cell text with whitespace collapsed). Fails when no table matches.
params: [selector]
timeout: 15000
script: |
  (() => {
    const selector = {{selector}};
    const table = document.querySelector(selector);
    if (!table) throw new Error('no table matches the selector ' + selector);
    const rows = [...table.querySelectorAll('tr')].map((tr) =>
      [...tr.querySelectorAll('th,td')].map((c) => c.textContent.replace(/\s+/g, ' ').trim()),
    );
    if (!rows.length) throw new Error('table ' + selector + ' has no rows');
    return rows;
  })()

